import { useEffect, useRef, useState } from 'react'
import { StyleProp, StyleSheet, ViewStyle } from 'react-native'
import { MotiView } from 'moti'
import { useChatStore } from '../store/chatStore'
import Markdown from 'react-native-markdown-display'
import { chatEmitter, ChatEvents } from '@/utils/emitter'

export const completeMarkdown = (fragment: string): string => {
	fragment = fragment.trim()
	type Frame = { opening: string; closing: string; isFence: boolean }
	const out: string[] = []
	const stack: Frame[] = []
	const n = fragment.length
	let i = 0
	while (i < n) {
		const ch = fragment[i]
		if (ch === undefined) break
		if (
			(ch === '`' && fragment.startsWith('```', i)) ||
			(ch === '~' && fragment.startsWith('~~~', i))
		) {
			const fence = fragment.slice(i, i + 3)
			out.push(fence)
			stack.push({ opening: fence, closing: fence, isFence: true })
			i += 3
			continue
		}
		if (stack.length > 0) {
			const topFrame = stack[stack.length - 1]
			if (topFrame?.isFence) {
				const topFence = topFrame.closing
				if (fragment.startsWith(topFence, i)) {
					out.push(topFence)
					stack.pop()
					i += topFence.length
				} else {
					out.push(ch)
					i += 1
				}
				continue
			}
		}
		if (ch === '`') {
			let j = i
			while (j < n && fragment[j] === '`') j++
			const ticks = fragment.slice(i, j)
			const top = stack[stack.length - 1]
			if (top && !top.isFence && top.closing === ticks) {
				out.push(ticks)
				stack.pop()
			} else {
				out.push(ticks)
				stack.push({ opening: ticks, closing: ticks, isFence: false })
			}
			i = j
			continue
		}
		if (ch === '*' || ch === '_' || ch === '~') {
			let j = i
			while (j < n && fragment[j] === ch && j - i < 3) j++
			const run = fragment.slice(i, j)
			const top = stack[stack.length - 1]
			if (top && !top.isFence && top.opening[0] === ch) {
				out.push(top.closing)
				stack.pop()
			} else {
				out.push(run)
				stack.push({ opening: run, closing: run, isFence: false })
			}
			i = j
			continue
		}
		const pairs: Record<string, string> = { '[': ']', '(': ')', '<': '>' }
		const closingChar = pairs[ch]
		if (closingChar) {
			out.push(ch)
			stack.push({ opening: ch, closing: closingChar, isFence: false })
			i += 1
			continue
		}
		if (ch === ']' || ch === ')' || ch === '>') {
			const top = stack[stack.length - 1]
			if (top && !top.isFence && top.closing === ch) {
				out.push(ch)
				stack.pop()
			} else {
				out.push(ch)
			}
			i += 1
			continue
		}
		out.push(ch)
		i += 1
	}
	const result = [...out]
	while (stack.length) {
		const frame = stack.pop()
		if (!frame) break
		const { closing, isFence } = frame
		const potential = result.join('') + closing
		const lastLine = potential.split('\n').pop() || ''
		const wouldCreateHR =
			/^[-]{3,}$/.test(lastLine.trim()) ||
			/^[*]{3,}$/.test(lastLine.trim()) ||
			/^[_]{3,}$/.test(lastLine.trim())
		if (!wouldCreateHR) {
			result.push(closing)
			if (isFence) result.push('\n')
		}
	}
	return result.join('')
}

export const useStreamingTypingEffect = (
	streamingText: string,
	typingIntervalMs: number,
	lastStreamingText: boolean = false
) => {
	const [displayText, setDisplayText] = useState('')
	const [isComplete, setIsComplete] = useState(false)
	const targetTextRef = useRef('')
	const intervalRef = useRef<NodeJS.Timeout | null>(null)
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const setCurrentMessageId = useChatStore((state) => state.setCurrentMessageId)
	const setChatState = useChatStore((state) => state.setChatState)
	useEffect(() => {
		const previousText = targetTextRef.current
		targetTextRef.current = streamingText

		const isCompletelyNewText =
			previousText && !streamingText.startsWith(previousText)

		if (isCompletelyNewText) {
			if (intervalRef.current) {
				clearInterval(intervalRef.current)
				intervalRef.current = null
			}
			setDisplayText('')
			setIsComplete(false)
		}

		if (!intervalRef.current && streamingText.length > 0) {
			intervalRef.current = setInterval(() => {
				setDisplayText((currentText) => {
					const targetText = targetTextRef.current
					if (currentText.length >= targetText.length) {
						if (intervalRef.current) {
							clearInterval(intervalRef.current)
							intervalRef.current = null
							setIsComplete(true)
						}
						return currentText
					}
					return targetText.substring(0, currentText.length + 1)
				})
			}, typingIntervalMs)
		}

		return () => {
			if (intervalRef.current) {
				clearInterval(intervalRef.current)
				intervalRef.current = null
			}
		}
	}, [streamingText, typingIntervalMs])

	useEffect(() => {
		if (isComplete && lastStreamingText && currentMessageId) {
			// streaming is done
			setChatState('READY')
			setCurrentMessageId(null)
			chatEmitter.emit(ChatEvents.STREAMING_DONE)
		}
	}, [
		isComplete,
		lastStreamingText,
		currentMessageId,
		setChatState,
		setCurrentMessageId
	])

	return { displayText, isComplete }
}

type StreamingTextProps = {
	text: string
	typingIntervalMs?: number
	containerStyle?: StyleProp<ViewStyle>
	customStyles?: StyleSheet.NamedStyles<any>
	lastStreamingText?: boolean
}

export const StreamingText = ({
	text,
	typingIntervalMs = 2,
	containerStyle,
	customStyles,
	lastStreamingText = false // triggers end streaming
}: StreamingTextProps) => {
	const { displayText, isComplete } = useStreamingTypingEffect(
		text,
		typingIntervalMs,
		lastStreamingText
	)

	const shouldAutoComplete = !isComplete
	const processedText = shouldAutoComplete
		? completeMarkdown(displayText)
		: displayText

	return (
		<MotiView
			from={{ opacity: 0 }}
			animate={{ opacity: 1 }}
			transition={{ type: 'timing', duration: 300 }}
			style={[{ gap: 12 }, containerStyle]}
		>
			<Markdown style={customStyles}>{processedText}</Markdown>
		</MotiView>
	)
}
